<script setup lang="ts">
import { computed, ref } from 'vue';
import { state, scope, change, ui } from '../state';
import { clone } from '../services/application-state';
import { generateSchedule } from '../domain/schedule-engine';
import { plannedOpportunityCoverage, previewScheduleRegeneration } from '../domain/schedule-preview';
import type { PlannedWeek } from '../domain/models';
import { validateScheduleWeeks } from '../domain/scheduling';
const settings=ref({...clone(state.value!.studio),allowedLocations:clone((state.value!.studio.allowedLocations??[]) as string[]),useLocations:!!state.value!.studio.useLocations});
const proposal=ref<PlannedWeek[]|null>(null),baseline=ref(''),summary=ref(''),editing=ref(-1),weekText=ref('');
const weeks=computed(()=>state.value!.studio.schedule??[]);
const coverage=computed(()=>plannedOpportunityCoverage(state.value!.requirements,weeks.value));
function preview(locks:boolean){try{proposal.value=generateSchedule(state.value!.requirements,state.value!.progress.scoutRecords,settings.value,scope.value,locks);const delta=locks?previewScheduleRegeneration(weeks.value,proposal.value):null;summary.value=delta?`${delta.changedUnlockedWeeks} unlocked weeks change; ${delta.lockedWeeksPreserved} locked weeks preserved.`:`Replace schedule with ${proposal.value.length} weeks.`;baseline.value=JSON.stringify({state:state.value,scope:scope.value});}catch(e){proposal.value=null;ui.error=String(e);}}
function apply(){if(baseline.value!==JSON.stringify({state:state.value,scope:scope.value})){ui.error='Data or Scout scope changed. Generate a fresh preview.';proposal.value=null;return;}if(change('Before schedule generation',s=>{Object.assign(s.studio,{strategy:settings.value.strategy,weeks:settings.value.weeks,capacity:settings.value.capacity,useLocations:settings.value.useLocations,allowedLocations:settings.value.allowedLocations,schedule:proposal.value!});})){proposal.value=null;}}
function lock(index:number,value:boolean){change('Before changing week lock',s=>{s.studio.schedule![index].locked=value;});settings.value.schedule=clone(weeks.value);}
function edit(index:number){editing.value=index;weekText.value=JSON.stringify(weeks.value[index],null,2);}
function saveWeek(){try{const week=JSON.parse(weekText.value) as PlannedWeek;validateScheduleWeeks([week],state.value!.requirements);if(change('Before week edit',s=>{if(s.studio.schedule![editing.value].locked)throw new Error('Unlock the week before editing.');s.studio.schedule![editing.value]=week;})){editing.value=-1;settings.value.schedule=clone(weeks.value);}}catch(e){ui.error=String(e);}}
function move(index:number){if(change('Before moving week',s=>{const ws=s.studio.schedule!;if(ws[index].locked||ws[index-1].locked)throw new Error('Unlock both weeks before moving.');[ws[index-1],ws[index]]=[ws[index],ws[index-1]];}))settings.value.schedule=clone(weeks.value);}
const locations=computed(()=>[...new Set(state.value!.requirements.flatMap(r=>{const l=r.locations as {preferred?:string;alternatives?:string[]}|undefined;return [l?.preferred,...(l?.alternatives??[])].filter((x):x is string=>!!x);}))]);
</script>
<template><section><p>Planning never marks Scout progress complete. Review the proposal before applying; regenerate preserves locked weeks.</p><div class="toolbar"><label>Strategy<select v-model="settings.strategy"><option value="progress">Scout progress first</option><option value="curriculum">Curriculum first</option><option value="location">Location-focused</option><option value="balanced">Balanced</option></select></label><label>Weeks<input v-model.number="settings.weeks" type="number" min="1" max="60"></label><label>Requirements / night<input v-model.number="settings.capacity" type="number" min="1" max="12"></label><label class="check"><input v-model="settings.useLocations" type="checkbox">Consider locations</label><button @click="settings.schedule=clone(weeks);preview(false)">Generate schedule</button><button @click="settings.schedule=clone(weeks);preview(true)">Regenerate unlocked</button></div><fieldset v-if="settings.useLocations"><legend>Allowed locations (empty means all)</legend><label v-for="location in locations" :key="location" class="check"><input v-model="settings.allowedLocations" type="checkbox" :value="location">{{location}}</label></fieldset>
 <section v-if="proposal" class="panel"><h2>Schedule preview</h2><p>{{summary}} Changed unlocked weeks lose their existing activity attachments.</p><button @click="apply">Apply proposed schedule</button><button @click="proposal=null">Cancel</button><details><summary>Review proposal</summary><p v-for="(w,i) in proposal" :key="i">Week {{i+1}} {{w.locked?'(locked)':''}} · {{w.requirementIds.join(', ')}}</p></details></section>
 <details class="panel"><summary>Forecast and planned opportunities</summary><p>{{weeks.length}} sessions · {{coverage.filter(c=>c.planned>0).length}} unique requirements planned · {{weeks.filter(w=>w.locked).length}} locked weeks</p><p>Opportunities are separate from earned evidence. Repeat targets can require additional sessions.</p><table><thead><tr><th>Requirement</th><th>Target</th><th>Planned</th><th>Still needed</th></tr></thead><tbody><tr v-for="c in coverage" :key="c.requirementId"><td><button @click="ui.requirementId=c.requirementId">{{c.requirementId}}</button></td><td>{{c.required}}</td><td>{{c.planned}}</td><td>{{c.outstanding}}</td></tr></tbody></table></details>
 <form v-if="editing>=0" class="panel" @submit.prevent="saveWeek"><h2>Edit Week {{editing+1}}</h2><label>Week fields (JSON)<textarea v-model="weekText" rows="18" /></label><button>Save week</button><button type="button" @click="editing=-1">Cancel</button></form>
 <div class="week-grid"><article v-for="(w,i) in weeks" :key="i" class="panel"><div class="toolbar"><h2>Week {{i+1}}</h2><label class="check"><input type="checkbox" :checked="w.locked" @change="lock(i,($event.target as HTMLInputElement).checked)">Lock</label></div><h3>{{w.title||'Unplanned'}}</h3><p>{{w.location||'Any location'}} · capacity {{w.capacity}} · max per stage {{w.stageLimit||4}}</p><div v-for="stage in [1,2,3]" :key="stage"><b>Stage {{stage}}</b><ul><li v-for="r in state!.requirements.filter(r=>w.requirementIds.includes(r.id)&&r.stage===stage)" :key="r.id"><button @click="ui.requirementId=r.id">{{r.text}}</button></li></ul></div><button :disabled="!!w.locked" @click="edit(i)">Edit skills and settings</button><button :disabled="!i||!!w.locked||!!weeks[i-1]?.locked" @click="move(i)">Move earlier</button><details v-if="w.activity"><summary>Stored attachment</summary><pre>{{JSON.stringify(w.activity,null,2)}}</pre></details></article></div><p v-if="!weeks.length">Generate a schedule or import an existing one in Data & State.</p></section></template>
